import type { Milestone, MilestoneProgress } from "@/types/milestone";

/**
 * Milestone domain rules that need no I/O: the state-conflict error, name
 * normalisation, the overdue predicate and the listing order.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const DEFAULT_MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "The milestone is closed.",
  already_open: "The milestone is already open.",
  too_many_open: "The project already has the maximum number of open milestones.",
  name_taken: "Another milestone in this project already has that name.",
};

/**
 * Thrown when a milestone is in the wrong state for the requested change, or
 * when the change would break a per-project invariant (the open-milestone cap,
 * unique names). Maps to `conflict` in `toAppError`.
 */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: MilestoneStateReason,
    detail?: string,
  ) {
    super(detail ?? DEFAULT_MESSAGES[reason]);
    this.name = "MilestoneStateError";
  }
}

/** The form of a name two milestones are compared by: trimmed, case-folded. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

export function isMilestoneOpen(milestone: Pick<Milestone, "closedAt">): boolean {
  return milestone.closedAt === null;
}

/** Epoch milliseconds of a target date, or `null` when unset or unparseable. */
function targetMillis(milestone: Pick<Milestone, "targetDate">): number | null {
  if (milestone.targetDate === null) return null;
  const millis = Date.parse(milestone.targetDate);
  return Number.isNaN(millis) ? null : millis;
}

/**
 * Overdue means: open, a target date strictly before `now`, and work left.
 * Without a target date a milestone can never be overdue.
 */
export function isMilestoneOverdue(
  milestone: Pick<Milestone, "closedAt" | "targetDate">,
  progress: Pick<MilestoneProgress, "open">,
  now: Date,
): boolean {
  if (!isMilestoneOpen(milestone) || progress.open <= 0) return false;
  const target = targetMillis(milestone);
  return target !== null && target < now.getTime();
}

/**
 * Listing order: open milestones before closed ones; within each group the
 * earliest target date first, undated last; ties by creation, oldest first.
 * The sort is stable, so callers that pass rows in insertion order get
 * insertion order for milestones created in the same millisecond.
 */
export function sortMilestones<T extends Milestone>(rows: readonly T[]): T[] {
  return [...rows].sort((a, b) => {
    const openA = isMilestoneOpen(a) ? 0 : 1;
    const openB = isMilestoneOpen(b) ? 0 : 1;
    if (openA !== openB) return openA - openB;

    const targetA = targetMillis(a);
    const targetB = targetMillis(b);
    if (targetA !== targetB) {
      if (targetA === null) return 1;
      if (targetB === null) return -1;
      return targetA - targetB;
    }

    return Date.parse(a.createdAt) - Date.parse(b.createdAt);
  });
}
EOF

