/**
 * Milestone rows and their issue counts. Every method takes `orgId` first.
 *
 * Each write that must hold an invariant (unique name, open-milestone cap,
 * one close per milestone, an open target) checks and writes inside a single
 * synchronous SQLite transaction, so two concurrent callers cannot both pass
 * the check. Refusals come back as a `reason`; turning them into domain errors
 * is the service's job.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, count, eq, inArray, isNotNull, isNull, notInArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type { Db } from "@/server/db";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

type Tx = Parameters<Parameters<Db["transaction"]>[0]>[0];
/** Anything a read can run on: the connection or an open transaction. */
type Reader = Db | Tx;

export type InsertMilestoneResult =
  | { readonly ok: true; readonly milestone: Milestone }
  | { readonly ok: false; readonly reason: "name_taken" | "too_many_open" };

export type UpdateMilestoneResult =
  | { readonly ok: true; readonly milestone: Milestone }
  | { readonly ok: false; readonly reason: "missing" | "name_taken" };

export type ReopenMilestoneResult =
  | { readonly ok: true; readonly milestone: Milestone }
  | {
      readonly ok: false;
      readonly reason: "missing" | "already_open" | "too_many_open";
    };

export type CloseMilestoneResult =
  | {
      readonly ok: true;
      readonly milestone: Milestone;
      readonly movedIssueIds: readonly IssueId[];
    }
  | {
      readonly ok: false;
      readonly reason: "missing" | "closed" | "target_missing" | "target_closed";
    };

/** Why an issue of `projectId` cannot be put into a milestone. */
export type MilestoneAssignment = "ok" | "not_found" | "closed";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project, closed ones included, in creation order. */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(milestones.createdAt, sql`${milestones}.rowid`)
    .all();
  return rows.map(toMilestone);
}

function countOpen(db: Reader, orgId: OrgId, projectId: ProjectId): number {
  const row = db
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

function nameTaken(
  db: Reader,
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): boolean {
  const rows = db
    .select({ id: milestones.id })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        eq(milestones.nameKey, milestoneNameKey(name)),
      ),
    )
    .all();
  return rows.some((row) => row.id !== exceptId);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return countOpen(getDb(), orgId, projectId);
}

/**
 * Whether an issue of `projectId` may be put into `milestoneId`: the milestone
 * must exist in this organization and project, and be open. Synchronous so a
 * caller can run it inside the same transaction as the write it guards.
 */
export function checkMilestoneAssignable(
  db: Reader,
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): MilestoneAssignment {
  const row = db
    .select({ projectId: milestones.projectId, closedAt: milestones.closedAt })
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  if (!row || row.projectId !== projectId) return "not_found";
  return row.closedAt === null ? "ok" : "closed";
}

export async function insertMilestone(
  input: {
    readonly orgId: OrgId;
    readonly projectId: ProjectId;
    readonly name: string;
    readonly targetDate: IsoTimestamp | null;
  },
  maxOpen: number,
): Promise<InsertMilestoneResult> {
  return getDb().transaction((tx): InsertMilestoneResult => {
    if (nameTaken(tx, input.orgId, input.projectId, input.name, null)) {
      return { ok: false, reason: "name_taken" };
    }
    if (countOpen(tx, input.orgId, input.projectId) >= maxOpen) {
      return { ok: false, reason: "too_many_open" };
    }

    const stamp = toIsoTimestamp(new Date());
    const row = tx
      .insert(milestones)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        name: input.name,
        nameKey: milestoneNameKey(input.name),
        targetDate: input.targetDate,
        closedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return { ok: true, milestone: toMilestone(row) };
  });
}

/** `undefined` leaves a field alone; `targetDate: null` clears it. */
export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    readonly name?: string;
    readonly targetDate?: IsoTimestamp | null;
  },
): Promise<UpdateMilestoneResult> {
  return getDb().transaction((tx): UpdateMilestoneResult => {
    const current = tx
      .select()
      .from(milestones)
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .get();
    if (!current) return { ok: false, reason: "missing" };

    if (
      patch.name !== undefined &&
      nameTaken(tx, orgId, current.projectId as ProjectId, patch.name, milestoneId)
    ) {
      return { ok: false, reason: "name_taken" };
    }

    if (patch.name === undefined && patch.targetDate === undefined) {
      return { ok: true, milestone: toMilestone(current) };
    }

    const row = tx
      .update(milestones)
      .set({
        ...(patch.name === undefined
          ? {}
          : { name: patch.name, nameKey: milestoneNameKey(patch.name) }),
        ...(patch.targetDate === undefined
          ? {}
          : { targetDate: patch.targetDate }),
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .returning()
      .get();

    return { ok: true, milestone: toMilestone(row) };
  });
}

export async function reopenMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  maxOpen: number,
  now: Date,
): Promise<ReopenMilestoneResult> {
  return getDb().transaction((tx): ReopenMilestoneResult => {
    const current = tx
      .select()
      .from(milestones)
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .get();
    if (!current) return { ok: false, reason: "missing" };
    if (current.closedAt === null) return { ok: false, reason: "already_open" };
    if (countOpen(tx, orgId, current.projectId as ProjectId) >= maxOpen) {
      return { ok: false, reason: "too_many_open" };
    }

    const row = tx
      .update(milestones)
      .set({ closedAt: null, updatedAt: toIsoTimestamp(now) })
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .returning()
      .get();

    return { ok: true, milestone: toMilestone(row) };
  });
}

/**
 * Closes a milestone and, in the same transaction, moves its open live issues
 * to `moveTo` (or out of any milestone when `null`). Closed and archived
 * issues are left where they are. `moveTo` must be another open milestone of
 * the same project.
 */
export async function closeMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
  now: Date,
): Promise<CloseMilestoneResult> {
  return getDb().transaction((tx): CloseMilestoneResult => {
    const current = tx
      .select()
      .from(milestones)
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .get();
    if (!current) return { ok: false, reason: "missing" };
    if (current.closedAt !== null) return { ok: false, reason: "closed" };

    if (moveTo !== null) {
      if (moveTo === milestoneId) return { ok: false, reason: "target_missing" };
      const assignable = checkMilestoneAssignable(
        tx,
        orgId,
        current.projectId as ProjectId,
        moveTo,
      );
      if (assignable === "not_found") {
        return { ok: false, reason: "target_missing" };
      }
      if (assignable === "closed") return { ok: false, reason: "target_closed" };
    }

    const stamp = toIsoTimestamp(now);

    const row = tx
      .update(milestones)
      .set({ closedAt: stamp, updatedAt: stamp })
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .returning()
      .get();

    const moved = tx
      .update(issues)
      .set({ milestoneId: moveTo, updatedAt: stamp })
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, milestoneId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      )
      .returning({ id: issues.id })
      .all();

    return {
      ok: true,
      milestone: toMilestone(row),
      movedIssueIds: moved.map((issue) => issue.id as IssueId),
    };
  });
}

/**
 * Issue counts per milestone over live issues, computed by the database so the
 * numbers do not depend on any page size. Milestones without issues are
 * absent from the map.
 */
export async function getMilestoneProgress(
  orgId: OrgId,
  scope: { readonly projectId: ProjectId } | { readonly milestoneId: MilestoneId },
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      total: count(),
      closed: sql<number>`coalesce(sum(case when ${inArray(issues.status, [...CLOSED_ISSUE_STATUSES])} then 1 else 0 end), 0)`,
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        livePredicate(issues.archivedAt, {}),
        isNotNull(issues.milestoneId),
        "projectId" in scope
          ? eq(issues.projectId, scope.projectId)
          : eq(issues.milestoneId, scope.milestoneId),
      ),
    )
    .groupBy(issues.milestoneId)
    .all();

  return new Map(
    rows.map((row) => [
      row.milestoneId as MilestoneId,
      { total: row.total, open: row.total - row.closed, closed: row.closed },
    ]),
  );
}

