  | { readonly ok: true; readonly issue: Issue }
  | {
      readonly ok: false;
      readonly reason:
        | "issue_missing"
        | "issue_archived"
        | "milestone_missing"
        | "milestone_closed";
    };

/**
 * Puts a live issue into an open milestone of its own project, or takes it
 * out with `null`. The checks and the write share one transaction, so a
 * milestone closed a moment earlier cannot receive the issue.
 */
export async function setIssueMilestone(
  orgId: OrgId,
  issueId: IssueId,
  milestoneId: MilestoneId | null,
): Promise<SetIssueMilestoneResult> {
  const outcome = getDb().transaction(
    (
      tx,
    ):
      | { ok: true; row: typeof issues.$inferSelect }
      | Extract<SetIssueMilestoneResult, { ok: false }> => {
      const current = tx
        .select()
        .from(issues)
        .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
        .get();
      if (!current) return { ok: false, reason: "issue_missing" };
      if (current.archivedAt !== null) {
        return { ok: false, reason: "issue_archived" };
      }

      if (milestoneId !== null) {
        const assignable = checkMilestoneAssignable(
          tx,
          orgId,
          current.projectId as ProjectId,
          milestoneId,
        );
        if (assignable === "not_found") {
          return { ok: false, reason: "milestone_missing" };
        }
        if (assignable === "closed") {
          return { ok: false, reason: "milestone_closed" };
        }
      }

      if (current.milestoneId === milestoneId) return { ok: true, row: current };

      const row = tx
        .update(issues)
        .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
        .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
        .returning()
        .get();
      return { ok: true, row };
    },
  );

  if (!outcome.ok) return outcome;

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return {
    ok: true,
    issue: toIssue(outcome.row, (labels[issueId] ?? []).map((label) => label.id)),
  };
}

/** Assignee per issue id (`null` when unassigned); unknown ids are absent. */
export async function listIssueAssignees(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<ReadonlyMap<IssueId, UserId | null>> {
  const assignees = new Map<IssueId, UserId | null>();
  const CHUNK = 500;

  for (let start = 0; start < issueIds.length; start += CHUNK) {
    const rows = getDb()
      .select({ id: issues.id, assigneeId: issues.assigneeId })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, issueIds.slice(start, start + CHUNK)),
        ),
      )
      .all();
    for (const row of rows) {
      assignees.set(row.id as IssueId, row.assigneeId as UserId | null);
    }
  }

  return assignees;
}

