/**
 * Milestone lifecycle: create, rename/retarget, close (moving the open issues
 * on), reopen, and the progress read model. Every write is gated like editing
 * the project itself, so an archived project's milestones are read-only.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived, isMilestoneOverdue, sortMilestones
 */
import { z } from "zod";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  MilestoneStateError,
  isMilestoneOverdue,
  sortMilestones,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { actorEnvelope, projectResource, requireFound } from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

/**
 * Importing the fan-out is what attaches the `milestone.closed` handler that
 * alerts the assignees of moved issues; like `event-registry`, nothing else
 * would load it for a caller that only touches milestones.
 */
import "./notification-service";

const NO_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

const milestoneNameSchema = z.string().trim().min(1).max(80);

/** Names are stored trimmed; one that is blank after trimming is rejected. */
function cleanName(name: string): string {
  return milestoneNameSchema.parse(name);
}

async function requireProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

/** Loads a milestone and its project for a write the actor must be allowed. */
async function loadForWrite(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await requireProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return { milestone, project };
}

/**
 * Creates an open milestone. The name must be new to the project (ignoring
 * case and surrounding spaces, closed milestones included) and the project
 * must have room for another open milestone.
 */
export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await requireProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const result = await milestoneRepo.insertMilestone(
    {
      orgId: input.orgId,
      projectId: project.id,
      name: cleanName(input.name),
      targetDate: input.targetDate ?? null,
    },
    MAX_OPEN_MILESTONES_PER_PROJECT,
  );
  if (!result.ok) throw new MilestoneStateError(result.reason);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: result.milestone.projectId,
  });

  return result.milestone;
}

/** Renames and/or retargets a milestone; open or closed. No event is published. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  await loadForWrite(actor, input.orgId, input.milestoneId);

  const result = await milestoneRepo.updateMilestone(
    input.orgId,
    input.milestoneId,
    {
      ...(input.name === undefined ? {} : { name: cleanName(input.name) }),
      ...(input.targetDate === undefined
        ? {}
        : { targetDate: input.targetDate }),
    },
  );
  if (!result.ok) {
    if (result.reason === "missing") {
      requireFound(null, "Milestone", input.milestoneId);
    }
    throw new MilestoneStateError(result.reason);
  }

  return result.milestone;
}

/**
 * Closes a milestone. Its open live issues go to `moveOpenIssuesTo` (another
 * open milestone of the project) or out of any milestone; closed and archived
 * issues stay. The assignees of the moved issues are alerted by the fan-out,
 * which listens for `milestone.closed`.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  await loadForWrite(actor, input.orgId, input.milestoneId);

  const target = input.moveOpenIssuesTo ?? null;
  const result = await milestoneRepo.closeMilestone(
    input.orgId,
    input.milestoneId,
    target,
    new Date(),
  );

  if (!result.ok) {
    switch (result.reason) {
      case "missing":
        return requireFound(null, "Milestone", input.milestoneId);
      case "target_missing":
        return requireFound(null, "Milestone", target ?? input.milestoneId);
      case "closed":
      case "target_closed":
        throw new MilestoneStateError("closed");
    }
  }

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: result.milestone.projectId,
    movedToMilestoneId: target,
    movedIssueIds: result.movedIssueIds,
  });

  return { milestone: result.milestone, movedIssueIds: result.movedIssueIds };
}

/** Reopens a closed milestone, unless the project is at its open-milestone cap. */
export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  await loadForWrite(actor, orgId, milestoneId);

  const result = await milestoneRepo.reopenMilestone(
    orgId,
    milestoneId,
    MAX_OPEN_MILESTONES_PER_PROJECT,
    new Date(),
  );
  if (!result.ok) {
    if (result.reason === "missing") {
      requireFound(null, "Milestone", milestoneId);
    }
    throw new MilestoneStateError(result.reason);
  }

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: result.milestone.projectId,
  });

  return result.milestone;
}

/**
 * Lists a project's milestones with progress, open ones first, then closed;
 * within each group earliest target date first (undated last), then oldest.
 * Works for an archived project.
 */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await requireProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const now = new Date();
  const [rows, progress] = await Promise.all([
    milestoneRepo.listMilestonesForProject(orgId, projectId),
    milestoneRepo.getMilestoneProgress(orgId, { projectId }),
  ]);

  return sortMilestones(rows).map((milestone) =>
    withProgress(milestone, progress.get(milestone.id) ?? NO_PROGRESS, now),
  );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await requireProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const now = new Date();
  const progress = await milestoneRepo.getMilestoneProgress(orgId, {
    milestoneId,
  });

  return withProgress(milestone, progress.get(milestone.id) ?? NO_PROGRESS, now);
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isMilestoneOverdue(milestone, progress, now),
  };
}

