/**
 * Milestones: lifecycle, guards, issue assignment, progress, events, audit
 * rows and the alerts raised when a milestone is closed.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { toAppError, isDomainError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import { listNotifications } from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { IssueStatus } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let detachAudit: Unsubscribe;
let projectCounter = 0;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

/** A fresh project in the tenant's org, so each test starts with no milestones. */
async function freshProject(owner: Tenant = tenant): Promise<ProjectId> {
  projectCounter += 1;
  const project = await projectRepo.insertProject({
    orgId: owner.org.id,
    name: `Project ${projectCounter}`,
    slug: `project-${projectCounter}`,
    key: `PRJ${projectCounter}`,
    description: null,
    visibility: "org",
    leadId: owner.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });
  return project.id;
}

function stamp(offsetDays: number): IsoTimestamp {
  return new Date(Date.now() + offsetDays * 86_400_000).toISOString() as IsoTimestamp;
}

async function create(
  projectId: ProjectId,
  name: string,
  targetDate: IsoTimestamp | null = null,
  actor: Actor = tenant.actors.member,
) {
  return milestoneService.createMilestone(actor, {
    orgId: actor.orgId,
    projectId,
    name,
    targetDate,
  });
}

let issueNumber = 0;

async function addIssue(
  projectId: ProjectId,
  milestoneId: MilestoneId | null,
  options: { status?: IssueStatus; assignee?: Actor; archived?: boolean } = {},
): Promise<IssueId> {
  issueNumber += 1;
  const issue = await issueRepo.insertIssue(
    issueInput(tenant.org.id, projectId, {
      title: `Issue ${issueNumber}`,
      assigneeId: options.assignee?.userId ?? null,
      milestoneId,
    }),
    tenant.userIds.member,
    issueNumber,
  );
  if (options.status !== undefined && options.status !== "backlog") {
    await issueRepo.setIssueStatus(tenant.org.id, issue.id, options.status);
  }
  if (options.archived === true) {
    await issueRepo.archiveIssue(tenant.org.id, issue.id);
  }
  return issue.id;
}

async function milestoneOf(issueId: IssueId): Promise<MilestoneId | null> {
  return (await issueRepo.findIssueById(tenant.org.id, issueId))?.milestoneId ?? null;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones", "enterprise");
  other = await createTenant("othermilestones", "growth");
  detachAudit = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

describe("milestone guards", () => {
  it("rejects an org outside the actor's workspace on every operation", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Guarded");
    const actor = tenant.actors.owner;
    const foreign = other.org.id;

    await expect(
      milestoneService.createMilestone(actor, { orgId: foreign, projectId, name: "x", targetDate: null }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.updateMilestone(actor, { orgId: foreign, milestoneId: milestone.id, name: "y" }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.closeMilestone(actor, { orgId: foreign, milestoneId: milestone.id, moveOpenIssuesTo: null }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.reopenMilestone(actor, foreign, milestone.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.listMilestones(actor, foreign, projectId),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.getMilestone(actor, foreign, milestone.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.setIssueMilestone(actor, { orgId: foreign, issueId: "x" as IssueId, milestoneId: null }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("treats another workspace's project or milestone as not found", async () => {
    const foreignProject = await freshProject(other);
    const foreignMilestone = await create(foreignProject, "Elsewhere", null, other.actors.member);

    await expect(create(foreignProject, "Mine")).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.getMilestone(tenant.actors.owner, tenant.org.id, foreignMilestone.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.closeMilestone(tenant.actors.owner, {
        orgId: tenant.org.id,
        milestoneId: foreignMilestone.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.listMilestones(tenant.actors.owner, tenant.org.id, foreignProject),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("needs project:update to write and project:read to read", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Permissions");
    const viewer = tenant.actors.viewer;

    await expect(create(projectId, "Nope", null, viewer)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      milestoneService.updateMilestone(viewer, { orgId: viewer.orgId, milestoneId: milestone.id, name: "Nope" }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      milestoneService.closeMilestone(viewer, { orgId: viewer.orgId, milestoneId: milestone.id, moveOpenIssuesTo: null }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const listed = await milestoneService.listMilestones(viewer, viewer.orgId, projectId);
    expect(listed.map((entry) => entry.milestone.id)).toEqual([milestone.id]);
    await expect(
      milestoneService.getMilestone(viewer, viewer.orgId, milestone.id),
    ).resolves.toMatchObject({ milestone: { id: milestone.id } });
  });

  it("refuses every write for an archived project but still lists", async () => {
    const projectId = await freshProject();
    const open = await create(projectId, "Open one");
    const closed = await create(projectId, "Closed one");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const issueId = await addIssue(projectId, open.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });
    const member = tenant.actors.member;

    await expect(create(projectId, "Late")).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.updateMilestone(member, { orgId: member.orgId, milestoneId: open.id, name: "Late" }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.closeMilestone(member, { orgId: member.orgId, milestoneId: open.id, moveOpenIssuesTo: null }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.reopenMilestone(member, member.orgId, closed.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.setIssueMilestone(member, { orgId: member.orgId, issueId, milestoneId: null }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const listed = await milestoneService.listMilestones(member, member.orgId, projectId);
    expect(listed).toHaveLength(2);
    await expect(milestoneService.getMilestone(member, member.orgId, open.id)).resolves.toBeDefined();
  });
});

describe("creating and changing milestones", () => {
  it("creates an open milestone with an optional target date", async () => {
    const projectId = await freshProject();
    const target = stamp(30);
    const dated = await create(projectId, "Dated", target);
    const undated = await create(projectId, "Undated");

    expect(dated).toMatchObject({ projectId, name: "Dated", targetDate: target, closedAt: null });
    expect(undated.targetDate).toBeNull();
  });

  it("keeps names unique per project regardless of case and spaces, closed ones included", async () => {
    const projectId = await freshProject();
    const first = await create(projectId, "Beta");

    for (const name of ["beta", "  BETA  ", "Beta"]) {
      await expect(create(projectId, name)).rejects.toMatchObject({
        name: "MilestoneStateError",
        reason: "name_taken",
      });
    }

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });
    await expect(create(projectId, "beta")).rejects.toMatchObject({ reason: "name_taken" });

    const elsewhere = await freshProject();
    await expect(create(elsewhere, "Beta")).resolves.toMatchObject({ name: "Beta" });
  });

  it("allows only one of two racing creations with the same name", async () => {
    const projectId = await freshProject();
    const results = await Promise.allSettled([
      create(projectId, "Racing"),
      create(projectId, " racing "),
    ]);
    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
    expect(results.filter((r) => r.status === "rejected")).toHaveLength(1);
  });

  it("caps open milestones per project; closed ones do not count", async () => {
    const projectId = await freshProject();
    const created: MilestoneId[] = [];
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      created.push((await create(projectId, `Cap ${i}`)).id);
    }

    await expect(create(projectId, "One too many")).rejects.toMatchObject({ reason: "too_many_open" });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: created[0] as MilestoneId,
      moveOpenIssuesTo: null,
    });
    const replacement = await create(projectId, "One too many");

    // Ten are open again, so the closed one cannot come back.
    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, created[0] as MilestoneId),
    ).rejects.toMatchObject({ reason: "too_many_open" });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: replacement.id,
      moveOpenIssuesTo: null,
    });
    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, created[0] as MilestoneId),
    ).resolves.toMatchObject({ closedAt: null });
  });

  it("renames and retargets, allows a case-only rename, refuses a taken name", async () => {
    const projectId = await freshProject();
    const a = await create(projectId, "Alpha");
    await create(projectId, "Omega");
    const member = tenant.actors.member;

    const renamed = await milestoneService.updateMilestone(member, {
      orgId: member.orgId,
      milestoneId: a.id,
      name: "ALPHA",
      targetDate: stamp(10),
    });
    expect(renamed.name).toBe("ALPHA");
    expect(renamed.targetDate).not.toBeNull();

    await expect(
      milestoneService.updateMilestone(member, { orgId: member.orgId, milestoneId: a.id, name: " omega " }),
    ).rejects.toMatchObject({ reason: "name_taken" });

    const cleared = await milestoneService.updateMilestone(member, {
      orgId: member.orgId,
      milestoneId: a.id,
      targetDate: null,
    });
    expect(cleared).toMatchObject({ name: "ALPHA", targetDate: null });

    const untouched = await milestoneService.updateMilestone(member, { orgId: member.orgId, milestoneId: a.id });
    expect(untouched).toEqual(cleared);
  });

  it("maps the state error to a conflict", () => {
    const error = new MilestoneStateError("closed");
    expect(error.code).toBe("conflict");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error)).toMatchObject({ code: "conflict", meta: { reason: "closed" } });
  });
});

describe("issues and milestones", () => {
  it("puts an issue into an open milestone of its own project when created", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Release");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, projectId, { title: "Inside", milestoneId: milestone.id }),
    );
    expect(issue.milestoneId).toBe(milestone.id);
    await expect(milestoneOf(issue.id)).resolves.toBe(milestone.id);
  });

  it("creates nothing and announces nothing when the milestone is refused", async () => {
    const projectId = await freshProject();
    const closed = await create(projectId, "Gone");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const otherProject = await freshProject();
    const elsewhere = await create(otherProject, "Not here");
    const foreign = await create(await freshProject(other), "Foreign", null, other.actors.member);

    const created = capture("issue.created");
    const before = await issueRepo.countIssues(tenant.org.id, projectId);

    await expect(
      issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, projectId, { milestoneId: closed.id })),
    ).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(
      issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, projectId, { milestoneId: elsewhere.id })),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, projectId, { milestoneId: foreign.id })),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(created).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, projectId)).toBe(before);
  });

  it("moves an issue between milestones and takes it out", async () => {
    const projectId = await freshProject();
    const a = await create(projectId, "A");
    const b = await create(projectId, "B");
    const issueId = await addIssue(projectId, null);
    const member = tenant.actors.member;

    const set = (milestoneId: MilestoneId | null) =>
      issueService.setIssueMilestone(member, { orgId: member.orgId, issueId, milestoneId });

    expect((await set(a.id)).milestoneId).toBe(a.id);
    expect((await set(b.id)).milestoneId).toBe(b.id);
    expect((await set(null)).milestoneId).toBeNull();
    await expect(milestoneOf(issueId)).resolves.toBeNull();
  });

  it("refuses closed, foreign-project and unknown milestones, and archived issues", async () => {
    const projectId = await freshProject();
    const closed = await create(projectId, "Closed");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const elsewhere = await create(await freshProject(), "Elsewhere");
    const issueId = await addIssue(projectId, null);
    const archivedId = await addIssue(projectId, null, { archived: true });
    const member = tenant.actors.member;
    const set = (id: IssueId, milestoneId: MilestoneId | null) =>
      issueService.setIssueMilestone(member, { orgId: member.orgId, issueId: id, milestoneId });

    await expect(set(issueId, closed.id)).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(set(issueId, elsewhere.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(set(issueId, "01HZZZMISSINGMISSINGMISSI0" as MilestoneId)).rejects.toBeInstanceOf(NotFoundError);
    await expect(set(archivedId, null)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(milestoneOf(issueId)).resolves.toBeNull();
  });

  it("lets a viewer who is the issue's author or assignee move it, but nobody else", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Escalation");
    const viewer = tenant.actors.viewer;
    const owned = await addIssue(projectId, null, { assignee: viewer });
    const foreignIssue = await addIssue(projectId, null);

    await expect(
      issueService.setIssueMilestone(viewer, { orgId: viewer.orgId, issueId: owned, milestoneId: milestone.id }),
    ).resolves.toMatchObject({ milestoneId: milestone.id });
    await expect(
      issueService.setIssueMilestone(viewer, { orgId: viewer.orgId, issueId: foreignIssue, milestoneId: milestone.id }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});

describe("progress and listing", () => {
  it("counts live issues only, however many there are", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Counted");

    for (let i = 0; i < 130; i += 1) {
      await addIssue(projectId, milestone.id, { status: i % 5 === 0 ? "done" : "todo" });
    }
    await addIssue(projectId, milestone.id, { status: "canceled" });
    await addIssue(projectId, milestone.id, { archived: true });
    await addIssue(projectId, null);

    const { progress } = await milestoneService.getMilestone(tenant.actors.viewer, tenant.org.id, milestone.id);
    expect(progress).toEqual({ total: 131, open: 104, closed: 27 });

    const [listed] = await milestoneService.listMilestones(tenant.actors.viewer, tenant.org.id, projectId);
    expect(listed?.progress).toEqual(progress);
  });

  it("is overdue only when open, strictly past its date, and still has open issues", async () => {
    const projectId = await freshProject();
    const pastWithWork = await create(projectId, "Past with work", stamp(-2));
    const pastDone = await create(projectId, "Past done", stamp(-2));
    const pastEmpty = await create(projectId, "Past empty", stamp(-2));
    const future = await create(projectId, "Future", stamp(2));
    const undated = await create(projectId, "Undated");
    await addIssue(projectId, pastWithWork.id);
    await addIssue(projectId, pastDone.id, { status: "done" });
    await addIssue(projectId, future.id);
    await addIssue(projectId, undated.id);

    const viewer = tenant.actors.viewer;
    const overdueOf = async (id: MilestoneId) =>
      (await milestoneService.getMilestone(viewer, viewer.orgId, id)).overdue;

    expect(await overdueOf(pastWithWork.id)).toBe(true);
    expect(await overdueOf(pastDone.id)).toBe(false);
    expect(await overdueOf(pastEmpty.id)).toBe(false);
    expect(await overdueOf(future.id)).toBe(false);
    expect(await overdueOf(undated.id)).toBe(false);

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: pastWithWork.id,
      moveOpenIssuesTo: null,
    });
    expect(await overdueOf(pastWithWork.id)).toBe(false);
  });

  it("orders open before closed, by target date with undated last, then oldest first", async () => {
    const projectId = await freshProject();
    const lateOpen = await create(projectId, "late open", stamp(20));
    const undatedFirst = await create(projectId, "undated first");
    const earlyOpen = await create(projectId, "early open", stamp(5));
    const undatedSecond = await create(projectId, "undated second");
    const tieA = await create(projectId, "tie a", stamp(10));
    const closedEarly = await create(projectId, "closed early", stamp(1));
    const closedUndated = await create(projectId, "closed undated");
    const sameDay = new Date(tieA.targetDate as string).toISOString() as IsoTimestamp;
    const tieB = await create(projectId, "tie b", sameDay);

    for (const m of [closedUndated, closedEarly]) {
      await milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: m.id,
        moveOpenIssuesTo: null,
      });
    }

    const listed = await milestoneService.listMilestones(tenant.actors.viewer, tenant.org.id, projectId);
    expect(listed.map((entry) => entry.milestone.id)).toEqual([
      earlyOpen.id,
      tieA.id,
      tieB.id,
      lateOpen.id,
      undatedFirst.id,
      undatedSecond.id,
      closedEarly.id,
      closedUndated.id,
    ]);
  });
});

describe("closing and reopening", () => {
  it("moves open live issues to the target and leaves closed and archived ones", async () => {
    const projectId = await freshProject();
    const from = await create(projectId, "From");
    const to = await create(projectId, "To");
    const open1 = await addIssue(projectId, from.id, { status: "todo" });
    const open2 = await addIssue(projectId, from.id, { status: "in_review" });
    const done = await addIssue(projectId, from.id, { status: "done" });
    const canceled = await addIssue(projectId, from.id, { status: "canceled" });
    const archived = await addIssue(projectId, from.id, { archived: true });

    const closedEvents = capture("milestone.closed");
    const result = await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: from.id,
      moveOpenIssuesTo: to.id,
    });

    expect(result.milestone.closedAt).not.toBeNull();
    expect([...result.movedIssueIds].sort()).toEqual([open1, open2].sort());
    await expect(milestoneOf(open1)).resolves.toBe(to.id);
    await expect(milestoneOf(open2)).resolves.toBe(to.id);
    await expect(milestoneOf(done)).resolves.toBe(from.id);
    await expect(milestoneOf(canceled)).resolves.toBe(from.id);
    await expect(milestoneOf(archived)).resolves.toBe(from.id);

    expect(closedEvents).toHaveLength(1);
    expect(closedEvents[0]).toMatchObject({
      milestoneId: from.id,
      projectId,
      movedToMilestoneId: to.id,
      actorId: tenant.userIds.member,
    });
    expect([...(closedEvents[0]?.movedIssueIds ?? [])].sort()).toEqual([open1, open2].sort());
  });

  it("takes the open issues out of any milestone when no target is named", async () => {
    const projectId = await freshProject();
    const from = await create(projectId, "Solo");
    const issueId = await addIssue(projectId, from.id);

    const result = await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: from.id,
      moveOpenIssuesTo: null,
    });
    expect(result.movedIssueIds).toEqual([issueId]);
    await expect(milestoneOf(issueId)).resolves.toBeNull();
  });

  it("refuses a bad close without changing or announcing anything", async () => {
    const projectId = await freshProject();
    const from = await create(projectId, "Stays");
    const closedTarget = await create(projectId, "Closed target");
    const foreignTarget = await create(await freshProject(), "Foreign target");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closedTarget.id,
      moveOpenIssuesTo: null,
    });
    const issueId = await addIssue(projectId, from.id);
    const events = capture("milestone.closed");
    const member = tenant.actors.member;
    const close = (moveOpenIssuesTo: MilestoneId | null) =>
      milestoneService.closeMilestone(member, { orgId: member.orgId, milestoneId: from.id, moveOpenIssuesTo });

    await expect(close(closedTarget.id)).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(close(from.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(close(foreignTarget.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(close("01HZZZMISSINGMISSINGMISSI0" as MilestoneId)).rejects.toBeInstanceOf(NotFoundError);

    expect(events).toHaveLength(0);
    await expect(milestoneOf(issueId)).resolves.toBe(from.id);
    const still = await milestoneService.getMilestone(member, member.orgId, from.id);
    expect(still.milestone.closedAt).toBeNull();
  });

  it("refuses closing a closed milestone and reopening an open one", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Twice");
    const member = tenant.actors.member;

    await expect(
      milestoneService.reopenMilestone(member, member.orgId, milestone.id),
    ).rejects.toMatchObject({ reason: "already_open" });

    const events = capture("milestone.closed");
    const close = () =>
      milestoneService.closeMilestone(member, { orgId: member.orgId, milestoneId: milestone.id, moveOpenIssuesTo: null });
    const results = await Promise.allSettled([close(), close()]);
    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
    expect(events).toHaveLength(1);

    await expect(close()).rejects.toMatchObject({ reason: "closed" });
  });

  it("reopens a closed milestone and publishes milestone.reopened once", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Back again");
    const member = tenant.actors.member;
    await milestoneService.closeMilestone(member, { orgId: member.orgId, milestoneId: milestone.id, moveOpenIssuesTo: null });

    const events = capture("milestone.reopened");
    const reopened = await milestoneService.reopenMilestone(member, member.orgId, milestone.id);

    expect(reopened.closedAt).toBeNull();
    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({ milestoneId: milestone.id, projectId, actorId: member.userId });
  });

  it("alerts each moved issue's assignee once, never the closer, never nobody's issue", async () => {
    const projectId = await freshProject();
    const from = await create(projectId, "Alerting");
    const to = await create(projectId, "Landing");
    const admin = tenant.actors.admin;
    const viewer = tenant.actors.viewer;
    const closer = tenant.actors.member;

    const forAdminOne = await addIssue(projectId, from.id, { assignee: admin });
    const forAdminTwo = await addIssue(projectId, from.id, { assignee: admin });
    const forViewer = await addIssue(projectId, from.id, { assignee: viewer });
    await addIssue(projectId, from.id, { assignee: closer });
    await addIssue(projectId, from.id);
    await addIssue(projectId, from.id, { assignee: viewer, status: "done" });

    await milestoneService.closeMilestone(closer, {
      orgId: closer.orgId,
      milestoneId: from.id,
      moveOpenIssuesTo: to.id,
    });

    const alertsFor = async (actor: Actor) =>
      (
        await listNotifications(tenant.actors.owner, {
          orgId: actor.orgId as OrgId,
          recipientId: actor.userId,
          unreadOnly: false,
          kind: ["issue_milestone_changed"],
          limit: 100,
          cursor: null,
        })
      ).items;

    const adminAlerts = await alertsFor(admin);
    const viewerAlerts = await alertsFor(viewer);
    expect(adminAlerts.map((a) => a.href).sort()).toEqual(
      [`/issues/${forAdminOne}`, `/issues/${forAdminTwo}`].sort(),
    );
    expect(viewerAlerts.map((a) => a.href)).toEqual([`/issues/${forViewer}`]);
    expect(await alertsFor(closer)).toHaveLength(0);
    expect(adminAlerts[0]?.actorId).toBe(closer.userId);
  });
});

describe("audit trail", () => {
  it("records created, closed and reopened with subject, project and actor", async () => {
    const projectId = await freshProject();
    const member = tenant.actors.member;
    const milestone = await create(projectId, "Audited");
    await milestoneService.closeMilestone(member, { orgId: member.orgId, milestoneId: milestone.id, moveOpenIssuesTo: null });
    await milestoneService.reopenMilestone(member, member.orgId, milestone.id);

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      subjectKind: "milestone",
      projectId,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((event) => event.action).sort()).toEqual([
      "milestone.closed",
      "milestone.created",
      "milestone.reopened",
    ]);
    for (const event of page.items) {
      expect(event).toMatchObject({
        subjectKind: "milestone",
        subjectId: milestone.id,
        projectId,
        actorId: member.userId,
      });
    }
  });
});

