/**
 * Milestones: lifecycle, guards, issue assignment, progress, events, audit
 * rows and the alerts raised when a milestone is closed.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { toAppError, isDomainError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import { listNotifications } from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { IssueStatus } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let detachAudit: Unsubscribe;
let projectCounter = 0;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

/** A fresh project in the tenant's org, so each test starts with no milestones. */
async function freshProject(owner: Tenant = tenant): Promise<ProjectId> {
  projectCounter += 1;
  const project = await projectRepo.insertProject({
    orgId: owner.org.id,
    name: `Project ${projectCounter}`,
    slug: `project-${projectCounter}`,
    key: `PRJ${projectCounter}`,
    description: null,
    visibility: "org",
    leadId: owner.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });
  return project.id;
}

function stamp(offsetDays: number): IsoTimestamp {
  return new Date(Date.now() + offsetDays * 86_400_000).toISOString() as IsoTimestamp;
}

async function create(
  projectId: ProjectId,
  name: string,
  targetDate: IsoTimestamp | null = null,
  actor: Actor = tenant.actors.member,
) {
  return milestoneService.createMilestone(actor, {
    orgId: actor.orgId,
    projectId,
    name,
    targetDate,
  });
}

let issueNumber = 0;

async function addIssue(
  projectId: ProjectId,
  milestoneId: MilestoneId | null,
  options: { status?: IssueStatus; assignee?: Actor; archived?: boolean } = {},
): Promise<IssueId> {
  issueNumber += 1;
  const issue = await issueRepo.insertIssue(
    issueInput(tenant.org.id, projectId, {
      title: `Issue ${issueNumber}`,
      assigneeId: options.assignee?.userId ?? null,
      milestoneId,
    }),
    tenant.userIds.member,
    issueNumber,
  );
  if (options.status !== undefined && options.status !== "backlog") {
    await issueRepo.setIssueStatus(tenant.org.id, issue.id, options.status);
  }
  if (options.archived === true) {
    await issueRepo.archiveIssue(tenant.org.id, issue.id);
  }
  return issue.id;
}

async function milestoneOf(issueId: IssueId): Promise<MilestoneId | null> {
  return (await issueRepo.findIssueById(tenant.org.id, issueId))?.milestoneId ?? null;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones", "enterprise");
  other = await createTenant("othermilestones", "growth");
  detachAudit = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

describe("milestone guards", () => {
  it("rejects an org outside the actor's workspace on every operation", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Guarded");
    const actor = tenant.actors.owner;
    const foreign = other.org.id;

    await expect(
      milestoneService.createMilestone(actor, { orgId: foreign, projectId, name: "x", targetDate: null }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.updateMilestone(actor, { orgId: foreign, milestoneId: milestone.id, name: "y" }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.closeMilestone(actor, { orgId: foreign, milestoneId: milestone.id, moveOpenIssuesTo: null }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.reopenMilestone(actor, foreign, milestone.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.listMilestones(actor, foreign, projectId),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.getMilestone(actor, foreign, milestone.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.setIssueMilestone(actor, { orgId: foreign, issueId: "x" as IssueId, milestoneId: null }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("treats another workspace's project or milestone as not found", async () => {
    const foreignProject = await freshProject(other);
    const foreignMilestone = await create(foreignProject, "Elsewhere", null, other.actors.member);

    await expect(create(foreignProject, "Mine")).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.getMilestone(tenant.actors.owner, tenant.org.id, foreignMilestone.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.closeMilestone(tenant.actors.owner, {
        orgId: tenant.org.id,
        milestoneId: foreignMilestone.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.listMilestones(tenant.actors.owner, tenant.org.id, foreignProject),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("needs project:update to write and project:read to read", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Permissions");
    const viewer = tenant.actors.viewer;

    await expect(create(projectId, "Nope", null, viewer)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      milestoneService.updateMilestone(viewer, { orgId: viewer.orgId, milestoneId: milestone.id, name: "Nope" }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      milestoneService.closeMilestone(viewer, { orgId: viewer.orgId, milestoneId: milestone.id, moveOpenIssuesTo: null }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const listed = await milestoneService.listMilestones(viewer, viewer.orgId, projectId);
    expect(listed.map((entry) => entry.milestone.id)).toEqual([milestone.id]);
    await expect(
      milestoneService.getMilestone(viewer, viewer.orgId, milestone.id),
    ).resolves.toMatchObject({ milestone: { id: milestone.id } });
  });

  it("refuses every write for an archived project but still lists", async () => {
    const projectId = await freshProject();
    const open = await create(projectId, "Open one");
    const closed = await create(projectId, "Closed one");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const issueId = await addIssue(projectId, open.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });
    const member = tenant.actors.member;

    await expect(create(projectId, "Late")).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.updateMilestone(member, { orgId: member.orgId, milestoneId: open.id, name: "Late" }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.closeMilestone(member, { orgId: member.orgId, milestoneId: open.id, moveOpenIssuesTo: null }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.reopenMilestone(member, member.orgId, closed.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.setIssueMilestone(member, { orgId: member.orgId, issueId, milestoneId: null }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const listed = await milestoneService.listMilestones(member, member.orgId, projectId);
    expect(listed).toHaveLength(2);
    await expect(milestoneService.getMilestone(member, member.orgId, open.id)).resolves.toBeDefined();
  });
});

describe("creating and changing milestones", () => {
  it("creates an open milestone with an optional target date", async () => {
    const projectId = await freshProject();
    const target = stamp(30);
    const dated = await create(projectId, "Dated", target);
    const undated = await create(projectId, "Undated");

    expect(dated).toMatchObject({ projectId, name: "Dated", targetDate: target, closedAt: null });
    expect(undated.targetDate).toBeNull();
  });

  it("keeps names unique per project regardless of case and spaces, closed ones included", async () => {
    const projectId = await freshProject();
    const first = await create(projectId, "Beta");

    for (const name of ["beta", "  BETA  ", "Beta"]) {
      await expect(create(projectId, name)).rejects.toMatchObject({
        name: "MilestoneStateError",
        reason: "name_taken",
      });
    }

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });
    await expect(create(projectId, "beta")).rejects.toMatchObject({ reason: "name_taken" });

    const elsewhere = await freshProject();
    await expect(create(elsewhere, "Beta")).resolves.toMatchObject({ name: "Beta" });
  });

  it("allows only one of two racing creations with the same name", async () => {
    const projectId = await freshProject();
    const results = await Promise.allSettled([
      create(projectId, "Racing"),
      create(projectId, " racing "),
    ]);
    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
    expect(results.filter((r) => r.status === "rejected")).toHaveLength(1);
  });

  it("caps open milestones per project; closed ones do not count", async () => {
    const projectId = await freshProject();
    const created: MilestoneId[] = [];
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      created.push((await create(projectId, `Cap ${i}`)).id);
    }

    await expect(create(projectId, "One too many")).rejects.toMatchObject({ reason: "too_many_open" });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: created[0] as MilestoneId,
      moveOpenIssuesTo: null,
    });
    const replacement = await create(projectId, "One too many");

    // Ten are open again, so the closed one cannot come back.
    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, created[0] as MilestoneId),
    ).rejects.toMatchObject({ reason: "too_many_open" });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: replacement.id,
      moveOpenIssuesTo: null,
    });
    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, created[0] as MilestoneId),
    ).resolves.toMatchObject({ closedAt: null });
  });

  it("renames and retargets, allows a case-only rename, refuses a taken name", async () => {
    const projectId = await freshProject();
    const a = await create(projectId, "Alpha");
    await create(projectId, "Omega");
    const member = tenant.actors.member;

    const renamed = await milestoneService.updateMilestone(member, {
      orgId: member.orgId,
      milestoneId: a.id,
      name: "ALPHA",
      targetDate: stamp(10),
    });
    expect(renamed.name).toBe("ALPHA");
    expect(renamed.targetDate).not.toBeNull();

    await expect(
