  });

  it("keeps update fields optional and a null target date meaningful", () => {
    expect(updateMilestoneSchema.parse({ orgId: ORG_A, milestoneId: MILESTONE })).toEqual({
      orgId: ORG_A,
      milestoneId: MILESTONE,
    });
    expect(
      updateMilestoneSchema.parse({ orgId: ORG_A, milestoneId: MILESTONE, targetDate: null }),
    ).toMatchObject({ targetDate: null });
  });

  it("defaults the close target to null and accepts a milestone id", () => {
    expect(closeMilestoneSchema.parse({ orgId: ORG_A, milestoneId: MILESTONE })).toMatchObject({
      moveOpenIssuesTo: null,
    });
    expect(
      closeMilestoneSchema.parse({ orgId: ORG_A, milestoneId: MILESTONE, moveOpenIssuesTo: MILESTONE }),
    ).toMatchObject({ moveOpenIssuesTo: MILESTONE });
  });

  it("requires an explicit milestone (or null) when setting an issue's milestone", () => {
    expect(setIssueMilestoneSchema.safeParse({ orgId: ORG_A, issueId: ISSUE }).success).toBe(false);
    expect(
      setIssueMilestoneSchema.safeParse({ orgId: ORG_A, issueId: ISSUE, milestoneId: null }).success,
    ).toBe(true);
    expect(
