/** The schema push creates the milestone table and column, and upgrades old databases. */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import Database from "better-sqlite3";
import { afterAll, describe, expect, it } from "vitest";
import { runMigrations } from "@/server/db/migrate";

const dirs: string[] = [];

function tempDb(): string {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-migrate-"));
  dirs.push(dir);
  return join(dir, "taskflow.db");
}

function columnsOf(path: string, table: string): string[] {
  const sqlite = new Database(path);
  try {
    return (sqlite.prepare(`PRAGMA table_info(${table})`).all() as { name: string }[]).map(
      (column) => column.name,
    );
  } finally {
    sqlite.close();
  }
}

afterAll(() => {
  for (const dir of dirs) rmSync(dir, { recursive: true, force: true });
});

describe("milestone migration", () => {
  it("gives a fresh database the milestones table and issues.milestone_id", async () => {
    const path = tempDb();
    await runMigrations(path);

    expect(columnsOf(path, "milestones")).toEqual(
      expect.arrayContaining(["id", "org_id", "project_id", "name", "target_date", "closed_at"]),
    );
    expect(columnsOf(path, "issues")).toContain("milestone_id");
  });

  it("adds the column to a database created before milestones, and is repeatable", async () => {
    const path = tempDb();
    const legacy = new Database(path);
    legacy.exec(
      `CREATE TABLE issues (id TEXT PRIMARY KEY NOT NULL, org_id TEXT NOT NULL, project_id TEXT NOT NULL,
         number INTEGER NOT NULL, title TEXT NOT NULL, author_id TEXT NOT NULL,
         created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT)`,
    );
    legacy.close();

    await runMigrations(path);
    await runMigrations(path);

    expect(columnsOf(path, "issues")).toContain("milestone_id");
    expect(columnsOf(path, "milestones")).toContain("name_key");
  });
});
